import{_ as i,o as t,c as n,a6 as r}from"./chunks/framework.BBdhcoHf.js";const p=JSON.parse('{"title":"Security Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/security-checklist.md","filePath":"protocols/sbrp/security-checklist.md","lastUpdated":1771970963000}'),a={name:"protocols/sbrp/security-checklist.md"};function o(s,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbrp/security-checklist.md for this page in Markdown format</div><h1 id="security-checklist" tabindex="-1">Security Checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to “Security Checklist”">​</a></h1><blockquote><p><strong>Authority</strong>: Supporting (Non-normative)<br><strong>Purpose</strong>: Auditor-facing verification checklist. Requirements are defined in <a href="./wire-crypto">wire-crypto.md</a> and <a href="./state-machine">state-machine.md</a>.</p></blockquote><p>This checklist summarizes security requirements from normative documents. For authoritative definitions, see the referenced specifications.</p><h2 id="daemon-security" tabindex="-1">Daemon Security <a class="header-anchor" href="#daemon-security" aria-label="Permalink to “Daemon Security”">​</a></h2><ul><li>[ ] Generate Ed25519 identity key on first run</li><li>[ ] Store identity private key with 0600 permissions</li><li>[ ] Include daemonId in signature payload (context binding)</li><li>[ ] Sign every ephemeral key with identity key</li><li>[ ] Use transcript hash as HKDF salt</li><li>[ ] Generate fresh X25519 ephemeral per session</li><li>[ ] Use directional keys (prevent reflection)</li><li>[ ] Implement bitmap-based sliding window (≥64 messages)</li><li>[ ] Send <code>Signal(ready)</code> for sessions with retained state after reconnect</li><li>[ ] Verify session state integrity before sending <code>Signal(ready)</code> after reconnect</li><li>[ ] Send <code>Signal(close, reason=state_lost)</code> for sessions with lost state after reconnect</li><li>[ ] Best-effort zero ephemeral keys and shared secrets after derivation</li><li>[ ] Best-effort clear all key material on session close</li></ul><h2 id="client-security" tabindex="-1">Client Security <a class="header-anchor" href="#client-security" aria-label="Permalink to “Client Security”">​</a></h2><ul><li>[ ] Pin identity key on first connection (TOFU)</li><li>[ ] Reject connections if identity key changes</li><li>[ ] Verify signature using pinned key, not freshly-fetched key</li><li>[ ] Include daemonId in signature verification payload</li><li>[ ] Use same transcript hash derivation as daemon</li><li>[ ] Handle <code>Control(session_paused/resumed/pending)</code> state transitions</li><li>[ ] Handle <code>Control(session_expired)</code> by initiating full reconnect</li></ul><h2 id="relay-security" tabindex="-1">Relay Security <a class="header-anchor" href="#relay-security" aria-label="Permalink to “Relay Security”">​</a></h2><ul><li>[ ] Implement rate limiting</li><li>[ ] Validate daemon ownership before routing</li><li>[ ] Wait for <code>Signal(ready)</code> from daemon before sending <code>Control(session_resumed)</code> to client</li><li>[ ] Send <code>Control(session_pending)</code> to client when daemon reconnects</li><li>[ ] Never log or inspect encrypted message payloads</li><li>[ ] Never include identifiers in Control message text</li><li>[ ] Respond to Ping with Pong, copying payload; never forward Ping/Pong</li></ul><h2 id="quick-connect-optional" tabindex="-1">Quick Connect (Optional) <a class="header-anchor" href="#quick-connect-optional" aria-label="Permalink to “Quick Connect (Optional)”">​</a></h2><ul><li>[ ] Disabled by default; require explicit operator opt-in</li><li>[ ] Enforce code expiry server-side (5 min TTL)</li><li>[ ] Rate-limit code generation</li><li>[ ] Use high-entropy codes (≥128 bits)</li></ul>',12)])])}const y=i(a,[["render",o]]);export{p as __pageData,y as default};
